laneYaml:
id: rt-excess-subagents
version: 1
priority: 2000
mode: enforce
purpose: Allow a small number of helper agents.
appliesTo: { surfaces: [claude-code], agents: ['rt-excess-subagents'] }
failMode: { default: closed, READ: open }
rules: { deny: [], allow: [], judge: [], approve: [] }
defaultVerdict: allow
approval: { channels: [dashboard], timeoutSec: 1 }
judge: { escalateBelow: 0.7, dataPolicy: redacted }
limits: { maxSubagents: 2, maxDepth: 5 }
